## Code Example
```c
// Minimal enqueue sketch (pseudo C)
struct Slot { uint64_t seq; char data[DATA_SZ]; };
volatile struct Slot *ring; // mapped
size_t head = 0; // per-producer index
size_t tail = 0; // consumer index
void enqueue(void *src){
  uint64_t s = fetch_add(&ring[head].seq, 1);
  // write data
  memcpy(ring[head].data, src, DATA_SZ);
  // publish
  ring[head].seq = s + 1;
  head = (head + 1) % RING_SIZE;
}
void dequeue(void *dst){
  uint64_t s = ring[tail].seq;
  if (s == expected){
    memcpy(dst, ring[tail].data, DATA_SZ);
    ring[tail].seq = s + 1;
    tail = (tail + 1) % RING_SIZE;
  }
}
```

